"""Offline first-command/contact analysis; does not run the simulation."""
import gzip,json,math,hashlib
from pathlib import Path
base=Path('out/tackle-breakthrough')
p=json.load(gzip.open(base/'game2-duo-tail-witness.json.gz'))
def dist(a,b):return math.hypot(a['x']-b['x'],a['y']-b['y'])
def at(t):return next(s for s in p['samples']if abs(s['t']-t)<1e-7)
def compact(t,slot):
 s=at(t);i=next(i for i,a in enumerate(s['agents'])if a['slot']==slot)
 pics=[q for q in p['pictures']if q['t']==s['t']and q['observer']==slot and q['target']=='RB']
 return {'t':s['t'],'agent':s['agents'][i],'carrier':s['agents'][6],'intent':s['intents'][i],'consumedCarrierPictures':list({json.dumps(q,sort_keys=True):q for q in pics}.values())}
nearest=[]
for i,a in enumerate(p['initial']['agents'][11:],11):
 s=min((s for s in p['samples']if s['carrier']=='RB'),key=lambda s:dist(s['agents'][i]['pos'],s['agents'][6]['pos']))
 nearest.append({'slot':a['slot'],'t':s['t'],'distance':dist(s['agents'][i]['pos'],s['agents'][6]['pos']),'defender':s['agents'][i],'carrier':s['agents'][6],'intent':s['intents'][i]})
report={'schema':'native-duo-first-controller-witness-v1','source':p['sourceBefore'],'toolSha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'inputSha256':hashlib.sha256((base/'game2-duo-tail-witness.json.gz').read_bytes()).hexdigest(),'gameIndex':2,'gameSeed':p['gameSeed'],'snapSeed':p['targetSeed'],'call':p['initial']['offCall']['label'],'defense':p['initial']['defCall']['label'],'context':p['initial']['snapContext'],'completeGameLogMatches':p['completeGameLogMatches'],'rawTargetResultMatches':p['rawTargetResultMatches'],'rawResult':{'offenseYards':p['result']['offenseYards'],'outcome':p['result']['outcome'],'duration':p['result']['duration'],'turnover':p['result']['turnover']},'handoffEvent':next(e for e in p['result']['events']if e['type']=='handoff'),'firstLBRunReadEvent':next(e for e in p['result']['events']if e['type']=='read'and e['a']==15 and e.get('note','').startswith('run')),'firstLBRetreatRequestAfterRunRead':next(compact(s['t'],'LB_M')for s in p['samples']if s['t']>=1.25 and s['intents'][15]['vel']['x']>0),'commandWitnesses':[compact(t,'LB_M')for t in [1.25,1.6,2,2.25,2.3]],'worldCarrierContacts':[{'t':s['t'],'contact':c}for s in p['samples']for c in s['contacts']if 6 in [c['i'],c['j']]],'carrierContactXValues':sorted({s['firstContactX']for s in p['samples']if s.get('firstContactX')is not None}),'nearestDefenders':nearest,'missedOrBrokenEvents':[e for e in p['result']['events']if e['type']in ['missed_tackle','broken_tackle','hit','wrap','tackle']],'sourceLocations':{'runBelief':'src/sim/recognition.ts:221-238 (global handoff flag after personal observation delay; picture has no possession member)','manTransition':'src/sim/behaviors/defense.ts:210-220 (live pursuit requires past-LOS, or run belief AND assigned receiver blocking cue)','manCushion':'src/sim/behaviors/defense.ts:240-273 (off-man cushion and observed release feed-forward)','installedFit':'src/sim/run-fits.ts:109-125 and 164-184; B,+y,insert,attack,spill,stack for this LB'},'findings':['LB_M commits to run at 1.25 s, but the man controller requires a blocking look from its assigned RB to execute the installed fit before past-LOS pursuit.','At 1.60 s, while his own consumed RB image is moving +3.23 yd/s, LB_M requests +0.51 yd/s in the same downfield direction and preserves a receiver cushion; requests rise to +5.29 at 2.00 s and +7.20 at 2.25 s.','At 2.30 s his acquired RB position first clears the LOS of 19.40, activating live pursuit and changing the request to -2.04 yd/s.','The installed job is B-gap insertion on the +y side, not a universal chase license. At 1.60 s its undeclared-crease depth is LOS+1.5, before subsequent observed motion would permit closing on the declared crease.','No RB body collision, recorded wrap/hit, missed/broken tackle, or non-null first-contact position occurs. This witness tests creating an attainable approach; it cannot diagnose strength, balance or grasp handling.'],'limits':['One outcome-selected native witness, not a bust rate or proof the touchdown should be prevented.','Run read is a belief; Recognition uses handoffAt after a delay, without a recorded visible-possession channel or sight obstruction. It is not a verified gaze/hand observation.','Body facing is not eye direction. No extra see, behavior or RNG calls were made.','No counterfactual controller repair was run. Improved fit transition can still lose to actual blocks, back cuts, player capabilities or wrong play-action reads.']}
(base/'game2-duo-tail-summary.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:report[k]for k in ['source','gameIndex','gameSeed','snapSeed','completeGameLogMatches','rawTargetResultMatches','rawResult','handoffEvent','firstLBRunReadEvent','findings','limits']},indent=2))
